import TeamLogo from '@/components/brand/TeamLogo';
import { cn } from '@/lib/utils';
import type { Rivalry } from '@/utils/leagueContent';
import type { HeadToHead } from '@/utils/schedule';
import { findNFLTeam } from '@/utils/nflTeams';
import { rivalryGames, yourScore, type Nemesis, type Resume, type YourGame } from '@/utils/frontOffice';
import { staggerStyle, teamVars } from './shared';
import { useLeague } from '@/context/LeagueContext';
import { matchPlayerByName } from '@/utils/leagueContent';
import { peekProps } from '@/components/peek/peekProps';
import { useLeagueContent } from '@/utils/leagueContent';
import { rivalryFilesOf } from '@/utils/rivalryFiles';
import { RivalryFileStrip } from '@/components/rivalry/RivalryFilesRow';

/** A rival player's name: press and hold for his quick look */
const RivalName = ({ name }: { name: string }) => {
  const { getAllPlayers } = useLeague();
  return <span {...peekProps(matchPlayerByName(name, getAllPlayers()))}>{name}</span>;
};

const GameLine = ({ g }: { g: YourGame }) => (
  <li className="flex items-center gap-2 rounded-md bg-black/40 px-2.5 py-1.5 text-sm">
    <span className={cn('fo-chip', g.won ? 'fo-chip--won' : 'fo-chip--lost')}>{g.won ? 'W' : 'L'}</span>
    <span className="font-display text-base">{g.roman || `Y${g.year}`}</span>
    <span className="text-xs text-muted-foreground">Y{g.year}</span>
    <span className="ml-auto flex min-w-0 items-center gap-1.5">
      <TeamLogo team={g.team} size={20} decorative />
      <span className="truncate text-xs text-muted-foreground">{findNFLTeam(g.team)?.name ?? g.team}</span>
      <span className="font-mono tabular-nums">{yourScore(g)}</span>
    </span>
  </li>
);

type Meeting = HeadToHead['meetings'][number];

const CHIP = { W: 'fo-chip--won', L: 'fo-chip--lost', T: 'fo-chip--tied' } as const;

/** One weekly-scores meeting: result, season and round, the coach's club, home or away, score (his first). */
const MeetingLine = ({ m }: { m: Meeting }) => (
  <li className="flex items-center gap-2 rounded-md bg-black/40 px-2.5 py-1.5 text-sm">
    <span className={cn('fo-chip', CHIP[m.result])}>{m.result}</span>
    <span className="font-display text-base">{m.season}</span>
    <span className="truncate text-xs text-muted-foreground">
      {m.round} · {m.site === 'home' ? 'home' : 'away'}
    </span>
    <span className="ml-auto flex min-w-0 shrink-0 items-center gap-1.5">
      <TeamLogo team={m.coachTeam} size={20} decorative />
      <span className="hidden truncate text-xs text-muted-foreground sm:inline">{findNFLTeam(m.coachTeam)?.name ?? m.coachTeam}</span>
      <span className="font-mono tabular-nums">
        {m.for}–{m.against}
      </span>
    </span>
  </li>
);

const h2hRecord = (h: HeadToHead) => `${h.w}–${h.l}${h.t ? `–${h.t}` : ''}`;

const record = (games: YourGame[]) => {
  const w = games.filter((g) => g.won).length;
  return `${w}–${games.length - w}`;
};

interface RivalsPanelProps {
  rivalries: Rivalry[];
  nemeses: Nemesis[];
  resume: Resume;
}

const RivalsPanel = ({ rivalries, nemeses, resume }: RivalsPanelProps) => {
  // A lasting rivalry (or a past one) has its own file: its meetings live there, the panel links to it
  const { content } = useLeagueContent();
  const files = rivalryFilesOf(content);
  return (
  <section aria-labelledby="fo-rivals" className="space-y-3">
    <h2 id="fo-rivals" className="section-title">
      Rivals
    </h2>
    <div className={cn('grid gap-3', rivalries.length && nemeses.length && 'lg:grid-cols-[minmax(0,1.15fr)_minmax(0,1fr)]')}>
      {rivalries.length > 0 && (
        <div className="flex flex-col gap-3">
          {rivalries.map((r, i) => {
            const games = rivalryGames(r, resume);
            const file = r.file ? files.find((f) => f.id === r.file) : undefined;
            const weekly = !file && r.games?.meetings.length ? r.games : null;
            const meetings = weekly ? [...weekly.meetings].sort((a, b) => Number(a.season.slice(1)) - Number(b.season.slice(1)) || a.week - b.week) : [];
            const team = findNFLTeam(r.team);
            const kicker = r.era ?? (r.source === 'weekly scores' ? 'Weekly scores' : '');
            return (
              <article
                key={r.id}
                className="fo-panel fo-rival stagger-in flex-1 space-y-3 p-4 sm:p-5"
                style={{ ...teamVars(r.team), ...staggerStyle(i) }}
                aria-labelledby={`fo-rival-${r.id}`}
              >
                <div className="flex flex-wrap items-center gap-3">
                  <TeamLogo team={team ?? r.team} size={56} decorative />
                  <div className="min-w-0 flex-1">
                    <p className="text-[11px] font-semibold uppercase tracking-[0.18em] text-muted-foreground">
                      Featured rivalry{kicker ? ` · ${kicker}` : ''}
                    </p>
                    <h3 id={`fo-rival-${r.id}`} className="font-display text-2xl uppercase leading-tight">
                      {r.rival === r.team ? (team?.fullName ?? r.rival) : <RivalName name={r.rival} />}
                      {team && r.rival !== r.team && <span className="text-muted-foreground">'s {team.name}</span>}
                    </h3>
                  </div>
                  {(games.length > 0 || weekly || file) && (
                    <div className="flex w-full shrink-0 gap-4 sm:w-auto sm:text-right">
                      {games.length > 0 && (
                        <div>
                          <p className="fo-vs text-3xl leading-none">{record(games)}</p>
                          <p className="text-[10px] uppercase tracking-wider text-muted-foreground">Your SB record</p>
                        </div>
                      )}
                      {(weekly || file) && (
                        <div>
                          <p className={cn('fo-vs leading-none', games.length ? 'text-2xl' : 'text-3xl')}>{file ? file.record.text.replace(/-/g, '–') : h2hRecord(weekly!)}</p>
                          <p className="text-[10px] uppercase tracking-wider text-muted-foreground">In the weekly scores</p>
                        </div>
                      )}
                    </div>
                  )}
                </div>
                {file ? (
                  <>
                    <p className="text-sm leading-relaxed text-foreground/85">
                      {file.status === 'lasting' ? 'A lasting rivalry' : 'A past rivalry'}: {file.games} meetings from {file.first} to {file.last},{' '}
                      {file.record.text} for the {file.coachTeam}, {file.pointsFor}-{file.pointsAgainst} on points.
                    </p>
                    <RivalryFileStrip file={file} className="w-full sm:w-auto" />
                  </>
                ) : (
                  <p className="text-sm leading-relaxed text-foreground/85">{r.summary}</p>
                )}
                {(r.ownerNotes ?? []).map((n) => (
                  <blockquote key={n.id} className="border-l-2 border-[hsl(var(--fo-team))] pl-3 text-sm italic text-foreground/90">
                    “{n.text}”
                    <span className="mt-1 block text-[11px] not-italic text-muted-foreground">From the commissioner{n.season ? ` · ${n.season}` : ''}</span>
                  </blockquote>
                ))}
                {(games.length > 0 || weekly) && (
                  <div className={cn('grid gap-3', games.length > 0 && weekly && 'sm:grid-cols-2')}>
                    {games.length > 0 && (
                      <div className="min-w-0 space-y-1.5">
                        {weekly && <p className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">Super Bowls</p>}
                        <ul className="space-y-1.5" aria-label={`Super Bowl meetings with ${r.rival}`}>
                          {games.map((g) => (
                            <GameLine key={g.year} g={g} />
                          ))}
                        </ul>
                      </div>
                    )}
                    {weekly && (
                      <div className="min-w-0 space-y-1.5">
                        <p className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">
                          Weekly scores · {weekly.meetings.length} {weekly.meetings.length === 1 ? 'game' : 'games'}
                        </p>
                        <ul className="space-y-1.5" aria-label={`Weekly-score meetings with ${r.rival}`}>
                          {meetings.map((m) => (
                            <MeetingLine key={`${m.season}-${m.week}`} m={m} />
                          ))}
                        </ul>
                      </div>
                    )}
                  </div>
                )}
              </article>
            );
          })}
        </div>
      )}
      {nemeses.length > 0 && (
        <div className="fo-panel space-y-3 p-4 sm:p-5">
          <div>
            <h3 className="font-display text-lg uppercase">Teams that beat you</h3>
            <p className="text-xs text-muted-foreground">Every Super Bowl loss, with your full head-to-head against that team.</p>
          </div>
          <ul className="divide-y divide-border/50">
            {nemeses.map((n, i) => {
              const team = findNFLTeam(n.team);
              const lossYears = n.games.filter((g) => !g.won).map((g) => `Y${g.year}`);
              return (
                <li key={n.team} className="stagger-in flex items-center gap-3 py-2.5" style={staggerStyle(i)}>
                  <TeamLogo team={team ?? n.team} size={36} decorative />
                  <div className="min-w-0 flex-1">
                    <p className="truncate font-semibold">{team?.fullName ?? n.team}</p>
                    <p className="truncate text-xs text-muted-foreground">
                      Beat you in {lossYears.join(', ')}
                      {n.wins ? ` · you won ${n.games.filter((g) => g.won).map((g) => `Y${g.year}`).join(', ')}` : ' · no revenge yet'}
                    </p>
                  </div>
                  <span className={cn('lamp', n.wins > n.losses ? 'text-accent' : n.wins < n.losses ? 'text-destructive' : '')}>
                    <span className="sr-only">Head to head: </span>
                    <b>{n.wins}</b>–{n.losses}
                  </span>
                </li>
              );
            })}
          </ul>
        </div>
      )}
    </div>
  </section>
  );
};

export default RivalsPanel;
